const input = $input.first().json || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
const err = execution.error || {};

function sanitize(value) {
  return String(value || 'Unknown automation error')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[redacted-email]')
    .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [redacted]')
    .replace(/v1=[0-9a-f]{32,128}/gi, 'v1=[redacted-sig]')
    .replace(/\b[0-9a-f]{32,}\b/gi, '[redacted-secret]')
    .slice(0, 400);
}

return [
  {
    json: {
      service: 'lendloop-n8n',
      severity: 'error',
      workflowId: String(workflow.id || 'unknown'),
      workflowName: String(workflow.name || 'unknown'),
      executionId: String(execution.id || 'unknown'),
      lastNodeExecuted: String(execution.lastNodeExecuted || 'unknown'),
      errorName: String(err.name || 'WorkflowError'),
      errorMessage: sanitize(err.message || err.description),
      occurredAt: new Date().toISOString(),
    },
  },
];
